import java.util.*;

public class Main {
    // Toy GitOps reconcile loop: compare desired (Git) with live (cluster).
    static List<String> reconcile(String[] desired, String[] live) {
        Set<String> haveNames = new TreeSet<>(), wantNames = new HashSet<>(), created = new HashSet<>();
        for (String l : live) haveNames.add(l.split("\\|")[0]);
        for (String d : desired) wantNames.add(d.split("\\|")[0]);
        List<String> actions = new ArrayList<>();
        for (String d : desired) {                 // only fields Git declares are compared
            String[] w = d.split("\\|");
            if (!haveNames.contains(w[0])) {
                if (created.add(w[0])) actions.add("create " + w[0]);
                continue;
            }
            for (String l : live) {
                String[] h = l.split("\\|");
                if (h[0].equals(w[0]) && h[1].equals(w[1]) && !h[2].equals(w[2]))
                    actions.add("patch " + w[0] + "." + w[1] + " " + h[2] + " -> " + w[2]);
            }
        }
        for (String n : haveNames)                 // in cluster, not in Git: prune (sorted)
            if (!wantNames.contains(n)) actions.add("delete " + n);
        return actions;
    }

    static String show(String[] a) {
        StringBuilder sb = new StringBuilder("[");
        for (int i = 0; i < a.length; i++) sb.append(i > 0 ? ", " : "").append("'").append(a[i]).append("'");
        return sb.append("]").toString();
    }

    public static void main(String[] args) {
        String[] desired = {"Deployment/web|replicas|3", "Deployment/web|image|web:1.4", "Service/web|port|80"};
        String[] live = {"Deployment/web|replicas|5", "Deployment/web|image|web:1.4",
                "Deployment/web|uid|abc", "Job/debug|image|busybox"};
        System.out.println("desired: " + show(desired));
        System.out.println("live: " + show(live));
        for (String a : reconcile(desired, live)) System.out.println(a);
        // Time O(D*L) here for clarity; with maps it is O(D+L). Space O(D+L).
    }
}

