// Toy GitOps reconcile loop: compare desired (Git) with live (cluster).
const desired = ["Deployment/web|replicas|3", "Deployment/web|image|web:1.4", "Service/web|port|80"];
const live = ["Deployment/web|replicas|5", "Deployment/web|image|web:1.4",
  "Deployment/web|uid|abc", "Job/debug|image|busybox"];

function reconcile(desired, live) {
  const want = desired.map(d => d.split("|"));
  const have = live.map(l => l.split("|"));
  const haveNames = new Set(have.map(h => h[0]));
  const wantNames = new Set(want.map(w => w[0]));
  const actions = [], created = new Set();
  for (const [name, field, value] of want) {   // only fields Git declares are compared
    if (!haveNames.has(name)) {
      if (!created.has(name)) { created.add(name); actions.push("create " + name); }
      continue;
    }
    for (const h of have) {
      if (h[0] === name && h[1] === field && h[2] !== value) {
        actions.push("patch " + name + "." + field + " " + h[2] + " -> " + value);
      }
    }
  }
  [...haveNames].filter(n => !wantNames.has(n)).sort().forEach(n => actions.push("delete " + n)); // prune
  return actions;
}

