import java.util.*;

public class Main {
    static final List<String> PHASES = Arrays.asList("PreSync", "Sync", "PostSync");
    static final List<String> KINDS = Arrays.asList("Namespace", "ConfigMap", "Service", "Deployment", "Job");

    // Order a sync: phase, then wave, then kind order, then name.
    static int compare(String a, String b) {
        String[] x = a.split(" "), y = b.split(" ");
        int c = Integer.compare(PHASES.indexOf(x[1]), PHASES.indexOf(y[1]));
        if (c != 0) return c;
        c = Integer.compare(Integer.parseInt(x[2]), Integer.parseInt(y[2])); // numeric: -1 < 0 < 10
        if (c != 0) return c;
        String[] rx = x[0].split("/"), ry = y[0].split("/");
        c = Integer.compare(KINDS.indexOf(rx[0]), KINDS.indexOf(ry[0]));
        return c != 0 ? c : rx[1].compareTo(ry[1]);
    }

    public static void main(String[] args) {
        List<String> items = new ArrayList<>(Arrays.asList("Deployment/web Sync 0", "Job/smoke PostSync 0",
                "Job/migrate PreSync 0", "Service/web Sync 0", "Namespace/shop Sync -1", "ConfigMap/cfg Sync 0"));
        StringBuilder sb = new StringBuilder("[");
        for (int i = 0; i < items.size(); i++) sb.append(i > 0 ? ", " : "").append("'").append(items.get(i)).append("'");
        System.out.println("input: " + sb + "]");
        items.sort(Main::compare);
        for (String item : items) {
            String[] p = item.split(" ");
            System.out.println(p[1] + " " + p[2] + ": " + p[0]);
        }
        // Time O(n log n), space O(n).
    }
}

