#include <bits/stdc++.h>
using namespace std;
// Order a sync: phase, then wave, then kind order, then name.
vector<string> PHASES = {"PreSync", "Sync", "PostSync"};
vector<string> KINDS = {"Namespace", "ConfigMap", "Service", "Deployment", "Job"};
int idx(const vector<string>& v, const string& s) { return find(v.begin(), v.end(), s) - v.begin(); }

tuple<int, int, int, string> key(const string& item) {
    stringstream ss(item);
    string ref, phase; int wave;
    ss >> ref >> phase >> wave;                     // wave parsed as int: -1 < 0 < 10
    size_t slash = ref.find('/');
    return {idx(PHASES, phase), wave, idx(KINDS, ref.substr(0, slash)), ref.substr(slash + 1)};
}

int main() {
    vector<string> items = {"Deployment/web Sync 0", "Job/smoke PostSync 0", "Job/migrate PreSync 0",
                            "Service/web Sync 0", "Namespace/shop Sync -1", "ConfigMap/cfg Sync 0"};
    cout << "input: [";
    for (size_t i = 0; i < items.size(); i++) cout << (i ? ", '" : "'") << items[i] << "'";
    cout << "]\n";
    sort(items.begin(), items.end(), [](const string& a, const string& b) { return key(a) < key(b); });
    for (auto& item : items) {
        stringstream ss(item);
        string ref, phase, wave;
        ss >> ref >> phase >> wave;
        cout << phase << " " << wave << ": " << ref << "\n";
    }
    // Time O(n log n), space O(n).
}

