using System;
using System.Collections.Generic;

class Program
{
    static readonly List<string> Phases = new List<string> { "PreSync", "Sync", "PostSync" };
    static readonly List<string> Kinds = new List<string> { "Namespace", "ConfigMap", "Service", "Deployment", "Job" };

    // Order a sync: phase, then wave, then kind order, then name.
    static int Compare(string a, string b)
    {
        string[] x = a.Split(' '), y = b.Split(' ');
        int c = Phases.IndexOf(x[1]).CompareTo(Phases.IndexOf(y[1]));
        if (c != 0) return c;
        c = int.Parse(x[2]).CompareTo(int.Parse(y[2]));   // numeric: -1 < 0 < 10
        if (c != 0) return c;
        string[] rx = x[0].Split('/'), ry = y[0].Split('/');
        c = Kinds.IndexOf(rx[0]).CompareTo(Kinds.IndexOf(ry[0]));
        return c != 0 ? c : string.CompareOrdinal(rx[1], ry[1]);
    }

    static void Main()
    {
        var items = new List<string> { "Deployment/web Sync 0", "Job/smoke PostSync 0", "Job/migrate PreSync 0",
            "Service/web Sync 0", "Namespace/shop Sync -1", "ConfigMap/cfg Sync 0" };
        Console.WriteLine("input: ['" + string.Join("', '", items) + "']");
        items.Sort(Compare);
        foreach (var item in items)
        {
            var p = item.Split(' ');
            Console.WriteLine(p[1] + " " + p[2] + ": " + p[0]);
        }
        // Time O(n log n), space O(n).
    }
}
